def transform(grid):
    h, w = len(grid), len(grid[0])

    for c in range(w):
        if len({row[c] for row in grid}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            shared = set(v for row in left for v in row) & set(v for row in right for v in row)
            color = next(iter(shared))
            return [
                [3 if left[r][j] == color and right[r][j] == color else 4
                 for j in range(min(len(left[r]), len(right[r])))]
                for r in range(h)
            ]

    r = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
    top, bottom = grid[:r], grid[r + 1:]
    shared = set(v for row in top for v in row) & set(v for row in bottom for v in row)
    color = next(iter(shared))
    return [
        [3 if top[i][j] == color and bottom[i][j] == color else 4
         for j in range(w)]
        for i in range(min(len(top), len(bottom)))
    ]
